def find_even_Pair(A, N):
    """Write a python function to count the pairs with xor as an even number."""
    if A is None:
        return 0
    items = A[:N] if N is not None else A
    even_count = 0
    odd_count = 0
    for value in items:
        if value % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    # xor is even iff its least-significant bit is 0, i.e. both numbers
    # have the same parity, so count pairs within each parity group.
    return even_count * (even_count - 1) // 2 + odd_count * (odd_count - 1) // 2
